#[cfg(test)]
mod codex_m2_readiness_review {
 use super::*;
 struct Fixture(PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
 fn fixture()->(Fixture,Connection){let root=std::env::temp_dir().join(format!("m2-codex-rereview-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir_all(&root).unwrap();let c=Connection::open(root.join("her-flight-deck.db")).unwrap();c.pragma_update(None,"foreign_keys","ON").unwrap();for m in crate::migrations(){c.execute_batch(m.sql).unwrap();}c.execute_batch("CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY);INSERT INTO schema_migrations VALUES(11);INSERT INTO study_materials(id,title,created_at,updated_at) VALUES('mat','Synthetic','2026-10-04','2026-10-04');").unwrap();crate::practice_sessions::run_legacy_conversion_at(&root).unwrap();crate::practice_sessions::save_practice_test_at(&root,"mat","Synthetic",r#"[{"question":"Synthetic","options":["A","B"],"correctIndex":0,"explanation":"","sourcePage":null}]"#,"synthetic").unwrap();(Fixture(root),c)}
 fn start(f:&Fixture,c:&Connection)->serde_json::Value {let v:String=c.query_row("SELECT id FROM practice_test_versions",[],|r|r.get(0)).unwrap();crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"start_or_resume","operationId":"20000000-0000-4000-8000-000000000001","materialId":"mat","versionId":v})).unwrap()}
 fn record(f:&Fixture,c:&Connection,s:&serde_json::Value){let i:String=c.query_row("SELECT id FROM practice_test_items",[],|r|r.get(0)).unwrap();crate::practice_sessions::save_practice_session_at(&f.0,&serde_json::json!({"action":"record_response","operationId":"20000000-0000-4000-8000-000000000002","attemptId":s["attemptId"],"itemId":i,"expectedRevision":0,"selectedIndex":1,"isDontKnow":false})).unwrap();}
 #[test]fn missing_source_fk_definition_refused(){let(f,c)=fixture();c.execute_batch("PRAGMA writable_schema=ON;UPDATE sqlite_master SET sql=replace(sql,' REFERENCES study_materials(id) ON DELETE SET NULL','') WHERE name='practice_test_versions';PRAGMA writable_schema=OFF;").unwrap();drop(c);let check=Connection::open(f.0.join("her-flight-deck.db")).unwrap();let n:i64=check.query_row("SELECT count(*) FROM pragma_foreign_key_list('practice_test_versions')",[],|r|r.get(0)).unwrap();assert_eq!(n,0);drop(check);assert!(verify_application_database(&f.0.join("her-flight-deck.db")).is_err(),"schema with missing source foreign key definition was accepted");}
 #[test]fn failed_semantic_validation_rolls_back_legacy_conversion(){let(f,c)=fixture();let s=start(&f,&c);record(&f,&c,&s);c.execute_batch("UPDATE practice_responses SET selected_index=99;INSERT INTO study_materials(id,title,created_at,updated_at) VALUES('legacy','Legacy synthetic','2026-10-04','2026-10-04');INSERT INTO practice_tests(source_material_id,title,questions_json,provider,model,generated_at,updated_at) VALUES('legacy','Legacy synthetic','[{\"question\":\"Synthetic\",\"options\":[\"A\",\"B\"],\"correctIndex\":0,\"explanation\":\"\",\"sourcePage\":null}]','gemini','synthetic','2026-10-04','2026-10-04');").unwrap();assert!(crate::practice_sessions::run_legacy_conversion_at(&f.0).is_err());let n:i64=c.query_row("SELECT count(*) FROM practice_test_versions WHERE source_material_id='legacy'",[],|r|r.get(0)).unwrap();let marker:Option<String>=c.query_row("SELECT legacy_migrated_at FROM practice_tests WHERE source_material_id='legacy'",[],|r|r.get(0)).unwrap();assert_eq!(n,0,"failed initialization committed a newly converted version");assert!(marker.is_none());}
}
